export const populateStateFromSavedQuery = (queryService, savedQuery) => {
  const {
    timefilter: {
      timefilter
    },
    filterManager,
    queryString
  } = queryService;
  // timefilter
  if (savedQuery.attributes.timefilter) {
    timefilter.setTime({
      from: savedQuery.attributes.timefilter.from,
      to: savedQuery.attributes.timefilter.to
    });
    if (savedQuery.attributes.timefilter.refreshInterval) {
      timefilter.setRefreshInterval(savedQuery.attributes.timefilter.refreshInterval);
    }
  }

  // query string
  queryString.setQuery({
    ...savedQuery.attributes.query,
    // We should keep the currently selected dataset intact
    dataset: queryString.getQuery().dataset
  });

  // filters
  const savedQueryFilters = savedQuery.attributes.filters || [];
  const globalFilters = filterManager.getGlobalFilters();
  filterManager.setFilters([...globalFilters, ...savedQueryFilters]);
};