// By default, OpenSearch surrounds matched values in <em></em>. This is not ideal because it is possible that
// the value could contain <em></em> in the value. We define these custom tags that we would never expect to see
// inside a field value.
export const highlightTags = {
  pre: '@opensearch-dashboards-highlighted-field@',
  post: '@/opensearch-dashboards-highlighted-field@'
};