import { get } from 'lodash';
import moment from 'moment-timezone';
import { i18n } from '@osd/i18n';
import { BUCKET_TYPES } from './bucket_agg_types';
import { BucketAggType } from './bucket_agg_type';
import { createFilterDateRange } from './create_filter/date_range';
import { OSD_FIELD_TYPES } from '../../../osd_field_types/types';
const dateRangeTitle = i18n.translate('data.search.aggs.buckets.dateRangeTitle', {
  defaultMessage: 'Date Range'
});
export const getDateRangeBucketAgg = ({
  isDefaultTimezone,
  getConfig
}) => new BucketAggType({
  name: BUCKET_TYPES.DATE_RANGE,
  title: dateRangeTitle,
  createFilter: createFilterDateRange,
  getKey({
    from,
    to
  }) {
    return {
      from,
      to
    };
  },
  getSerializedFormat(agg) {
    return {
      id: 'date_range',
      params: agg.params.field ? agg.aggConfigs.indexPattern.getFormatterForField(agg.params.field).toJSON() : {}
    };
  },
  makeLabel(aggConfig) {
    return aggConfig.getFieldDisplayName() + ' date ranges';
  },
  params: [{
    name: 'field',
    type: 'field',
    filterFieldTypes: OSD_FIELD_TYPES.DATE,
    default(agg) {
      return agg.getIndexPattern().timeFieldName;
    }
  }, {
    name: 'ranges',
    default: [{
      from: 'now-1w/w',
      to: 'now'
    }]
  }, {
    name: 'time_zone',
    default: undefined,
    // Implimentation method is the same as that of date_histogram
    serialize: () => undefined,
    write: (agg, output) => {
      const field = agg.getParam('field');
      let tz = agg.getParam('time_zone');
      if (!tz && field) {
        tz = get(agg.getIndexPattern(), ['typeMeta', 'aggs', 'date_range', field.name, 'time_zone']);
      }
      if (!tz) {
        const detectedTimezone = moment.tz.guess();
        const tzOffset = moment().format('Z');
        tz = isDefaultTimezone() ? detectedTimezone || tzOffset : getConfig('dateFormat:tz');
      }
      output.params.time_zone = tz;
    }
  }]
});