import { nodeTypes } from '../node_types/index';
import { DQLSyntaxError } from '../kuery_syntax_error';
// @ts-ignore
import { parse as parseKuery } from './_generated_/kuery';
const fromExpression = (expression, parseOptions = {}, parse = parseKuery) => {
  if (typeof expression === 'undefined') {
    throw new Error('expression must be a string, got undefined instead');
  }
  return parse(expression, {
    ...parseOptions,
    helpers: {
      nodeTypes
    }
  });
};
export const fromLiteralExpression = (expression, parseOptions = {}) => {
  return fromExpression(expression, {
    ...parseOptions,
    startRule: 'Literal'
  }, parseKuery);
};
export const fromKueryExpression = (expression, parseOptions = {}) => {
  try {
    return fromExpression(expression, parseOptions, parseKuery);
  } catch (error) {
    if (error.name === 'SyntaxError') {
      throw new DQLSyntaxError(error, expression);
    } else {
      throw error;
    }
  }
};
export const doesKueryExpressionHaveLuceneSyntaxError = expression => {
  try {
    fromExpression(expression, {
      errorOnLuceneSyntax: true
    }, parseKuery);
    return false;
  } catch (e) {
    return e.message.startsWith('Lucene');
  }
};

/**
 * @params {String} indexPattern
 * @params {Object} config - contains the dateFormatTZ
 *
 * IndexPattern isn't required, but if you pass one in, we can be more intelligent
 * about how we craft the queries (e.g. scripted fields)
 */
export const toOpenSearchQuery = (node, indexPattern, config, context) => {
  if (!node || !node.type || !nodeTypes[node.type]) {
    return toOpenSearchQuery(nodeTypes.function.buildNode('and', []), indexPattern);
  }
  const nodeType = nodeTypes[node.type];
  return nodeType.toOpenSearchQuery(node, indexPattern, config, context);
};