import { createOsdFieldTypes, OsdFieldTypeUnknown } from './osd_field_types_factory';
import { OSD_FIELD_TYPES } from './types';

/** @private */
const registeredOsdTypes = createOsdFieldTypes();
let osdFieldOverrides = {};

/**
 *  Get a type object by name
 *
 *  @param  {string} typeName
 *  @return {OsdFieldType}
 */
export const getOsdFieldType = typeName => registeredOsdTypes.find(t => t.name === typeName) || OsdFieldTypeUnknown;

/**
 *  Get the esTypes known by all osdFieldTypes
 *
 *  @return {Array<string>}
 */
export const getOsdTypeNames = () => registeredOsdTypes.filter(type => type.name).map(type => type.name);

/**
 *  Get the OsdFieldType name for an opensearchType string
 *
 *  @param {string} opensearchType
 *  @return {string}
 */
export const castOpenSearchToOsdFieldTypeName = opensearchType => {
  const type = registeredOsdTypes.find(t => t.esTypes.includes(opensearchType));
  return type && type.name ? type.name : OSD_FIELD_TYPES.UNKNOWN;
};

/**
 *  Get filterable osdFieldTypes
 *
 *  @return {Array<string>}
 */
export const getFilterableOsdTypeNames = () => registeredOsdTypes.filter(type => type.filterable).map(type => type.name);
export const setOsdFieldOverrides = newOverrides => {
  osdFieldOverrides = newOverrides ? Object.assign({}, osdFieldOverrides, newOverrides) : {};
};
export const getOsdFieldOverrides = () => {
  return osdFieldOverrides;
};